    @login_logout
    def perform_bts_full_commissioning(self, scf_file, bts_id=0, skip_parameter_relation_errors=False,
                                       should_activate=True, validate_scf=True, timeout=300, du_id=0):
        """
        Perform Full BTS commissioning.

        :param scf_file: Path to the scf file
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param skip_parameter_relation_errors: Skip parameter relation errors
        :param should_activate: Should automatically activate plan
        :param validate_scf:    Should automatically validate plan
        :param timeout: Timeout for the operation. It is based on observed test times
        :return: None.
        """

        timeout = time_to_seconds(time=timeout)
        skip_parameter_relation_errors = to_boolean(item=skip_parameter_relation_errors)
        should_activate = to_boolean(item=should_activate)
        validate_scf = to_boolean(item=validate_scf)
        connection = self.rest_alias.format(bts_id, du_id)

        try:
            if validate_scf:
                validation_result = self._validate_scf(scf_file=scf_file, bts_id=bts_id, du_id=du_id)
                logging.info("Validation result: {}".format(validation_result))
            self.admin.perform_commissioning(scf_file=scf_file,
                                             skip_parameter_relation_errors=skip_parameter_relation_errors,
                                             should_activate=should_activate,
                                             timeout=timeout, connection=connection)
        except AdminApiProcedureFailureException:
            raise ValidationError("Validation error occurred and configuration should be rejected")
        else:
            logging.info("Validation passed")

    @login_logout
    def perform_bts_delta_json_commissioning(self, delta_file, bts_id=0, skip_parameter_relation_errors=False,
                                             should_activate=True, timeout=300, du_id=0,
                                             interface='mplane', force_reconnect=False):
        """
        Perform delta recommissioning using delta SCF file in json format.

        Sample delta_scf as template:
        *Note: Use pattern __MRBTS_ID__ and __NRBTS_ID__, it will be updated to actual values for BTS
        [
            {
                "distName": "MRBTS-__MRBTS_ID__/MNL-1/MNLENT-1/MPLANENW-1",
                "operation": "update",
                "parameters": [
                    {
                        "parameterName": "certTypeForTlsAuth",
                        "value": "ECDSA",
                        "operation": "update"
                    },
                    {
                        "parameterName": "mPlaneIpv4AddressDN",
                        "value": "MRBTS-__MRBTS_ID__/TNLSVC-1/TNL-1/IPNO-1/IPIF-5/IPADDRESSV4-1",
                        "operation": "update"
                    },
                    {
                        "parameterName": "oamTls",
                        "value": "forced",
                        "operation": "update"
                    },
                    {
                        "parameterName": "tls12Enabled",
                        "value": "true",
                        "operation": "update"
                    }
                ]
            }
        ]

        :param string delta_file: Path to Delta SCF JSON file.
        :param bts_id: ID of gNB/eNB
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param bool should_activate: Should automatically activate plan
        :param Union[int,str] timeout: Time to wait for positive procedure result
        :param str interface:  connect via 'mplane' or 'lmp'
        :param boolean force_reconnect:  True/False - If True - first disconnect adminCli if already connected.
        :return dict: Recommissioning status
        """
        delta_file = self._generate_delta_scf_from_template(delta_file, bts_id, du_id)
        return self.admin.perform_delta_recommissioning(delta_file, skip_parameter_relation_errors, should_activate,
                                                        timeout, connection=self.rest_alias.format(bts_id, du_id))

    def _generate_delta_scf_from_template(self, delta_template_path, bts_id, du_id):
        scf_params_to_replace = {'MRBTS_ID': self.get_bts_instance_id(bts_id=bts_id, du_id=du_id),
                                 'NRBTS_ID': self.get_global_bts_id(bts_id=bts_id, du_id=du_id)}
        with open(delta_template_path, 'r') as f_delta_template:
            delta_scf = f_delta_template.read()

        for k, v in scf_params_to_replace.items():
            delta_scf = delta_scf.replace('__{}__'.format(str(k).upper()), str(v))
        return delta_scf

    @login_logout
    def perform_bts_delta_commissioning(self, delta, bts_id=0, skip_parameter_relation_errors=False,
                                        should_activate=True, timeout=300, du_id=0, adjust_dist_name=True):
        """
        Perform parameter recommissioning, update and delete operation can be used.

        :param list delta: list of parameters to update. Sample delta:
                delta = [{
                            'distName': dist_name,
                            'operation': 'update',
                            'parameters': [{
                                            'operation': operation,
                                            'parameterName': parameter,
                                            'value': value}]}]
                where:
                    dist_name: Object dist name ie. "MRBTS-{}/LNBTS-{}/LNMME-0"
                    parameter: Parameter name ie. "ipAddrPrim"
                    operation: Parameter operation (update or delete)
                    value: Parameter value ie. "10.0.1.99" or [{"eea1":0, "eea0":1, "eea3":8, "eea2":0}]
        :param bts_id: ID of gNB/eNB
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param bool should_activate: Should automatically activate plan
        :param Union[int,str] timeout: Time to wait for positive procedure result
        :param bool adjust_dist_name: Adjust dist name to current bts_id and du_id
        :raises taf.gnb.oam.coam.admin.legacy.exceptions.AdminApiProcedureFailureException: Will be raised if
            recommissioning fails
        :return dict: Recommissioning status
        """
        timeout = time_to_seconds(time=timeout)
        skip_parameter_relation_errors = to_boolean(item=skip_parameter_relation_errors)
        should_activate = to_boolean(item=should_activate)

        if adjust_dist_name:
            for param_dict in delta:
                param_dict['distName'] = self.adjust_dist_name(dist_name=param_dict['distName'],
                                                               bts_id=bts_id, du_id=du_id)

        parameters = {"planObjects": delta, "shouldBeActivated": should_activate}

        connection = self.admin.store.get(self.rest_alias.format(bts_id, du_id))

        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True
        status = connection._api_client.execute_procedure("recommission", parameters, timeout)
        if status is None:
            raise DataNotAvailable("Recommissioning status has not been provided by M-Plane.")
        return status

