    @login_logout
    def verify_configuration_rejection(self, scf_file, bts_id=0, skip_parameter_relation_errors=False,
                                       should_activate=False, timeout=60, du_id=0):
        """
        Verify if configuration was rejected

        :param scf_file: Path to the scf file
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param skip_parameter_relation_errors: Skip parameter relation errors
        :param should_activate: Should automatically activate plan
        :param timeout: Timeout for the operation. It is based on observed test times
        :return: None.
        """

        timeout = time_to_seconds(time=timeout)
        skip_parameter_relation_errors = to_boolean(item=skip_parameter_relation_errors)
        should_activate = to_boolean(item=should_activate)

        try:
            self.admin.perform_commissioning(scf_file=scf_file,
                                             skip_parameter_relation_errors=skip_parameter_relation_errors,
                                             should_activate=should_activate,
                                             timeout=timeout,
                                             connection=self.rest_alias.format(bts_id, du_id))

        except AdminApiProcedureFailureException:
            logging.info("Configuration has been rejected successfully")

        else:
            raise ValidationError("This configuration should be rejected")

    def _validate_scf(self, bts_id=0, scf_file=None, local_dir_path="/tmp/", file_name="scf.xml", timeout=180,
                      du_id=0, skip_parameter_relation_errors=False):
        """
        Validate SCF file and return validation result
        :param bts_id: ID of gNB/eNB
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param str file_name: File name of final SCF
        :param str local_dir_path: Path to directory to store final SCF
        :param str scf_file: Path to the SCF file
        :param Union[int,str] timeout: Timeout for the operation
        :raises taf.gnb.oam.coam.admin.legacy.exceptions.AdminApiProcedureFailureException: Will be raised if
        validation failed
        :param skip_parameter_relation_errors: Flag whether to skip relation errors. Default False.
        :return: str: SCF validation result.
            validation_result = {
                                    "niddValidationResult": {"status": "OK",
                                                             "logs": {"skippedElements": null,
                                                                      "missingObjectsErrors": null,
                                                                      "definitionErrors": null,
                                                                                    "maxOccurrencesErrors": null}},
                                    "pdlValidationResult": {"status": "OK",
                                                            "logs": {"hardwareErrors": [], "relationErrors": []}}
                                }
        """
        connection = self.rest_alias.format(bts_id, du_id)
        scf = scf_file if scf_file else self.admin.get_current_scf_file(local_dir_path, file_name, timeout, connection)
        return self.admin.validate_scf_online(scf_file=scf, timeout=timeout, connection=connection,
                                              skip_parameter_relation_errors=skip_parameter_relation_errors)

