    @login_logout
    def perform_configuration_parameter_recommissioning(self, dist_name, parameter, operation, value,
                                                        bts_id=0, skip_parameter_relation_errors=False,
                                                        should_activate=True, timeout=60, du_id=0):
        """
        Perform recommissioning of specified configuration parameter on bts.

        :param dist_name:object dist name ie. "MRBTS-{}/LNBTS-{}/LNMME-0" or "MRBTS-{}/NRBTS-{}/NRCELL-1"
        :type  dist_name: str
        :param parameter: parameter name ie. "ipAddrPrim"
        :type  parameter: str
        :param operation: parameter operation (update or delete)
        :type  operation: str
        :param value: parameter value ie. "locked" or "unlocked"
        :type  value: str
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration, default 0
        :type  bts_id: int
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :type  du_id: int
        :param skip_parameter_relation_errors: If True then skip parameter relation errors, default False
        :type  skip_parameter_relation_errors: bool
        :param should_activate: If True activate plan automatically, default True
        :type  should_activate: bool
        :param timeout: Time to wait for positive procedure result, default 60
        :type  timeout: int
        :return: None
        """
        self.perform_parameter_recommissioning(dist_name=dist_name, parameter=parameter, operation=operation,
                                               value=value, bts_id=bts_id, should_activate=should_activate,
                                               skip_parameter_relation_errors=skip_parameter_relation_errors,
                                               timeout=timeout, du_id=du_id)

    @login_logout
    def reset_configuration(self, bts_id=0, du_id=0, timeout=900, remove_operator_certificates=False,
                            remove_user_account_credentials=False, repair_center_reset=False, detailed_output=False,
                            reset_type=None, wait_for_admin_connection=True, wait_for_admin_connection_timeout=500,
                            remove_wifi_configuration=False):
        """
        Reset configuration

        :param int bts_id: BTS(eNB/gNB) id - related to Test Line configuration, default 0
        :param int du_id: DU id - related to Test Line configuration, default 0
        :param int timeout: Time to wait for positive procedure result, default 60
        :param boolean remove_operator_certificates: Remove operator certificates
        :param boolean remove_user_account_credentials: Remove user account credentials
        :param boolean repair_center_reset: Remove all from both partitions
        :param boolean remove_wifi_configuration: Remove WiFi configuration too (WithWifi option)
        :param bool detailed_output: return full request response when True, defaults set to False
        :param boolean wait_for_admin_connection: Wait for admin connection after configuration reset
        :param int wait_for_admin_connection_timeout: timeout for admin connection after configuration reset
        :param str reset_type: Type of the performed reset - used only for legacy solution.
            Added via CNI-70685. One of: ["Configuration"|
            "ConfigurationWithSecurityCredentials"|"ConfigurationWithOperatorCertificates"|
            "ConfigurationWithLocalUserCredentials"|"ConfigurationWithResetOnlyActivePartitionAndRestoreNcf"]
        :return: None
        """

        active_sw_version = self.admin.get_sw_version(timeout=60, connection=self.rest_alias.format(bts_id, du_id))
        logging.info("Detected Software: {}".format(active_sw_version))
        asw = SbtsSwVersion(active_sw_version)
        if not RawSwValidator.fsm3(active_sw_version) and \
                ((asw.is_trunk_build() and asw >= SbtsSwVersion('SBTS23R4_ENB_9999_230601_000007'))
                 or (not asw.is_trunk_build() and asw >= SbtsSwVersion('SBTS23R3_ENB_0000_000080_000000'))):

            logging.debug("Build is >= [SBTS23R4_ENB_9999_230601_000007, SBTS23R3_ENB_0000_000080_000000] - "
                          "Use new configuration reset procedure(via Rescue Console)")
            self._reset_configuration_cb007500(
                remove_operator_certificates=remove_operator_certificates,
                remove_user_account_credentials=remove_user_account_credentials,
                repair_center_reset=repair_center_reset,
                remove_wifi_configuration=remove_wifi_configuration,
                timeout=timeout,
                detailed_output=detailed_output,
                bts_id=bts_id,
                du_id=du_id
            )
        else:
            logging.debug("Use legacy configuration reset")
            self.admin.reset_configuration(
                remove_operator_certificates=remove_operator_certificates,
                remove_user_account_credentials=remove_user_account_credentials,
                timeout=timeout,
                detailed_output=detailed_output,
                reset_type=reset_type,
                connection=self.rest_alias.format(bts_id, du_id))

        if wait_for_admin_connection:
            logging.debug("BTS is booting after configuration reset. "
                          "Waiting max {} seconds for ping".format(wait_for_admin_connection_timeout))
            # wait 30 sec for BTS is pingable
            time.sleep(30)
            start_time = time.time()
            while time.time() < start_time + wait_for_admin_connection_timeout:
                if self.lmp_is_pingable_from_ws(bts_id=bts_id, du_id=du_id):
                    break
                else:
                    time.sleep(30)
            logging.debug("Sleep additionally 60 sec for ADMIN availability")
            time.sleep(60)
            self.connect(interface='lmp', force=True, bts_id=bts_id, du_id=du_id, timeout=30, reconnect_attempts=10)

    def _reset_configuration_cb007500(self, remove_operator_certificates=False,
                                      remove_user_account_credentials=False, repair_center_reset=False,
                                      remove_wifi_configuration=False,
                                      timeout=900, detailed_output=False, bts_id=0, du_id=0):
        """
        Reset configuration in new way introduced in CB007500
        Steps:
            1. Run reset configuration from ADMIN CLI with reset_type="ConfigurationWithDiagnosticAndRecoverySw"
            2. BTS is booted to FDSW partition
            3. Connect to FDSW and check slot id for 'Active' partition
            4. Run software rollback with proper reset_type
            5. BTS is booted to target software with cleared configuration

        :param boolean remove_operator_certificates: Remove operator certificates
        :param boolean remove_user_account_credentials: Remove user account credentials
        :param boolean repair_center_reset: Remove all from both partitions
        :param boolean remove_wifi_configuration: Remove WiFi configuration too (WithWifi option)
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param int timeout: Timeout for the operation
        :param int bts_id: BTS(eNB/gNB) id - related to Test Line configuration, default 0
        :param int du_id: DU id - related to Test Line configuration, default 0
        :return
        """

        rc_connection = rc()
        coam_rest_alias = self.rest_alias.format(bts_id, du_id)
        fdsw_alias = self.fdsw_alias.format(bts_id, du_id)
        fdsw_ip = self.coam_used_ip.get(coam_rest_alias, '192.168.255.129')
        fdsw_port = 443
        local_host = 'localhost'

        admin_c = self.admin.store.get(coam_rest_alias)
        remote_host = admin_c._api_client.process.remote_host
        remote_host_username = admin_c._api_client.process.ssh_username
        remote_host_password = admin_c._api_client.process.ssh_password

        all_fdsw_params = [
            {'ssh_host': remote_host,
             'ssh_port': 22,
             'ssh_username': remote_host_username,
             'ssh_password': remote_host_password,
             'local_host': local_host,
             'local_port': 8561,
             'fdsw_alias': fdsw_alias
             }]

        if self._is_dual_core_configuration(connection=coam_rest_alias):
            secondary_remote_credentials = tl_config.get_bts_ws_credentials(bts_id=bts_id, du_id=du_id,
                                                                            common_unit_id=1)
            all_fdsw_params.append(
                {'ssh_host': secondary_remote_credentials['host'],
                 'ssh_port': 22,
                 'ssh_username': secondary_remote_credentials['user'],
                 'ssh_password': secondary_remote_credentials['password'],
                 'local_host': local_host,
                 'local_port': 8562,
                 'fdsw_alias': '{}_SECONDARY_CONNECTION'.format(fdsw_alias)
                 })
            all_fdsw_params[0]['fdsw_alias'] = '{}_PRIMARY_CONNECTION'.format(fdsw_alias)

        try:
            self.admin.reset_configuration(reset_type="ConfigurationWithDiagnosticAndRecoverySw",
                                           connection=coam_rest_alias,
                                           detailed_output=detailed_output,
                                           timeout=120)
        except Exception as e:
            logging.warning("Some exception occurred during reset configuration operation: {}".format(repr(e)))

        self.disconnect(bts_id=bts_id, du_id=du_id)

        remote_connections = []
        for fdsw_params in all_fdsw_params:
            if fdsw_params['ssh_host']:
                logging.info("Setup remote tunnel - SERVER: {}, PORT: {}".format(fdsw_params['ssh_host'],
                                                                                 fdsw_params['local_port']))
                copy_of_fdsw_params = fdsw_params.copy()
                del copy_of_fdsw_params['fdsw_alias']
                remote_connection = rc_connection.setup_remote(**copy_of_fdsw_params)
                remote_connections.append(remote_connection)

                fdsw_port = fdsw_params['local_port']
                fdsw_ip = fdsw_params['local_host']

            self._fdsw_software_rollback(
                reset_params={
                    "remove_operator_certificates": remove_operator_certificates,
                    "remove_user_account_credentials": remove_user_account_credentials,
                    "repair_center_reset": repair_center_reset,
                    "remove_wifi_configuration": remove_wifi_configuration},
                rc_connection=rc_connection,
                fdsw_connection_alias=fdsw_params['fdsw_alias'],
                timeout=timeout,
                fdsw_ip=fdsw_ip,
                fdsw_port=fdsw_port)

        if remote_connections:
            for remote_connection in remote_connections:
                rc_connection.disconnect_remote(remote_connection)

    def _fdsw_software_rollback(self, reset_params, rc_connection, fdsw_connection_alias='FDSW_CONNECTION',
                                timeout=900, fdsw_ip='192.168.255.129', fdsw_port=443, bts_id=0, du_id=0):

        self._wait_for_rc_connection(rc_connection=rc_connection,
                                     fdsw_connection_alias=fdsw_connection_alias,
                                     bts_id=bts_id,
                                     du_id=du_id,
                                     timeout=timeout,
                                     interval=20,
                                     port=fdsw_port,
                                     fdsw_ip=fdsw_ip)

        software_inventory = rc_connection.get_all_software_inventory(connection=fdsw_connection_alias)
        logging.debug("SOFTWARE INVENTORY: {}".format(software_inventory))
        target_slot_id = rc_connection.get_active_sw_partition(connection=fdsw_connection_alias)
        config_reset_options = self._get_supported_config_reset_options_for_proper_slot(software_inventory,
                                                                                        target_slot_id)
        logging.debug("SUPPORTED CONFIG RESET OPTIONS for SLOT_ID: {}  {}".format(target_slot_id, config_reset_options))
        config_reset_type = self._get_proper_config_reset_type(config_reset_options, **reset_params)
        logging.debug("Perform Software Rollback with parameters: sw_slot_id={}, reset_type={}".
                      format(target_slot_id, config_reset_type))
        rc_connection.software_rollback(sw_slot_id=target_slot_id,
                                        reset_type=config_reset_type,
                                        connection=fdsw_connection_alias,
                                        timeout=120)

    def _is_dual_core_configuration(self, connection):
        bts_info = self.admin.get_bts_info(connection=connection, timeout=30)
        if len(bts_info['systemModules']) == 2:
            return True
        return False

    @staticmethod
    def _get_supported_config_reset_options_for_proper_slot(software_inventory, target_slot_id):
        for slot_info in software_inventory['slots']:
            if int(target_slot_id) == int(slot_info['id']):
                return slot_info['supported_config_reset_options']

    @staticmethod
    def _get_proper_config_reset_type(config_reset_options, remove_operator_certificates,
                                      remove_user_account_credentials, repair_center_reset, remove_wifi_configuration):
        """
        +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
        | GUI Options                                                                                                                   | Description                                      | reset_type value            |
        +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
        | Default                                                                                                                       | warm reset(no configuration removal)             |                             |
        +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
        | Delete BTS configuration from active partition                                                                                |                                                  | FromActive                  |
        +-------------------------------------------------------------------------------------------------------------------------------+                                                  +-----------------------------+
        | Delete BTS configuration with installed operator certificates from active partition                                           |                                                  | WithCertFromActive          |
        +-------------------------------------------------------------------------------------------------------------------------------+ configuration reset - only from active partition +-----------------------------+
        | Delete BTS configuration with credentials from active partition                                                               |                                                  | WithCredsFromActive         |
        +-------------------------------------------------------------------------------------------------------------------------------+                                                  +-----------------------------+
        | Delete BTS configuration with installed operator certificates and credentials from active partition                           |                                                  | WithCertsAndCredsFromActive |
        +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
        | Delete BTS configuration with all operator provided data including the security credentials from active and passive partition | repair center reset(both partitions)             | RepairCenterReset           |
        +-------------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------+-----------------------------+
        """  # noqa: E501
        if repair_center_reset:
            reset_type = 'RepairCenterReset'
        elif remove_operator_certificates and remove_user_account_credentials:
            reset_type = 'WithCertsAndCredsFromActive'
        elif remove_operator_certificates:
            reset_type = 'WithCertFromActive'
        elif remove_user_account_credentials:
            reset_type = 'WithCredsFromActive'
        else:
            reset_type = 'FromActive'

        if isinstance(config_reset_options[0], (list, tuple)):
            reset_type = [reset_type]
            if remove_wifi_configuration and not repair_center_reset:
                reset_type.append("WithWifi")

        return reset_type

    def _wait_for_rc_connection(self, rc_connection, fdsw_connection_alias, bts_id=0, du_id=0,
                                timeout=180, interval=20, port=443, fdsw_ip='192.168.255.129'):
        credentials = tl_config.get_web_credentials_for_du(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        start_time = time.time()
        logging.info("Connect to Rescue Console: IP: {}, USERNAME: {}, PASSWORD: {}, PORT: {}, ALIAS: {}".
                     format(fdsw_ip, credentials['username'], credentials['password'], port, fdsw_connection_alias))

        while time.time() < start_time + timeout:
            try:
                rc_connection.connect_to(ip_address=fdsw_ip,
                                         username=credentials['username'],
                                         password=credentials['password'],
                                         port=port,
                                         secure=True,
                                         name=fdsw_connection_alias)
                break
            except Exception as e:
                logging.debug("Cannot connect to Rescue Console {}".format(repr(e)))
                logging.debug("Waiting {} sec for next attempt".format(interval))
                time.sleep(interval)
        else:
            raise Exception("Timeout passed for connection to Rescue Console")
        time.sleep(5)

