    @login_logout_GUI
    def verify_parameter_after_change(self, dist_name, parameter, value, bts_id=0, du_id=0):
        """
        Verify parameter after change via GUI
        :param dist_name:object dist name ie. "MRBTS-{}/NRBTS-{}/NRPGRP-0"
        :type  dist_name: str
        :param parameter: parameter name ie. "ipAddrPrim"
        :type  parameter: str
        :param value: parameter value ie. "locked" or "unlocked"
        :type  value: str
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration, default 0
        :type  bts_id: int
        :param du_id: DU id - related to Test Line configuration, default 0
        :type  du_id: int
        :return: None
        """
        gui_alias = self.gui_alias.format(bts_id, du_id)
        parameter_value = self.gui_coam.get_parameter_value(
            dist_name=self.adjust_dist_name(dist_name=dist_name, bts_id=bts_id, du_id=du_id),
            filter_param=parameter, sbts=gui_alias)
        if parameter_value != value:
            raise InvalidParameterValue("{} value should be: {}, but is: {}".format(parameter, value, parameter_value))
        self.gui_coam.validate_plan(sbts=gui_alias)

        active_sw = self.admin.get_sw_version(timeout=10, connection=self.rest_alias.format(bts_id, du_id))
        active_sw_version = SwVersionFactory.create_sw_version(active_sw)

        if (
            active_sw_version.is_trunk_build() and active_sw_version >= SbtsSwVersion('SBTS25R2_ENB_9999_250206_000012')
        ) or (
                not active_sw_version.is_trunk_build() and active_sw_version >= SbtsSwVersion(
                    'SBTS25R2_ENB_0000_000000_000000')):
            if self.gui_coam.get_relation_errors(sbts=gui_alias) or self.gui_coam.get_definition_errors(sbts=gui_alias):
                raise ValidationError
        else:
            if self.gui_coam.get_relation_errors(sbts=gui_alias) or self.gui_coam.get_hardware_errors(sbts=gui_alias)\
                    or self.gui_coam.get_definition_errors(sbts=gui_alias):
                raise ValidationError

